<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Advertiser,SponsorshipLead,User};use Illuminate\Http\Request;use Illuminate\Support\Str;use Inertia\Inertia;
class SponsorshipLeadController extends Controller{public function index(Request $r){$q=SponsorshipLead::with(['advertiser','owner'])->latest();if($r->filled('stage'))$q->where('stage',$r->stage);if($r->filled('search'))$q->where(fn($x)=>$x->where('company_name','like','%'.$r->search.'%')->orWhere('contact_name','like','%'.$r->search.'%'));return Inertia::render('Admin/Sponsorship/Leads/Index',['leads'=>$q->get(),'filters'=>$r->only(['stage','search'])]);}public function create(){return Inertia::render('Admin/Sponsorship/Leads/Form',['lead'=>null,'advertisers'=>Advertiser::orderBy('name')->get(['id','name']),'users'=>User::orderBy('name')->get(['id','name'])]);}public function store(Request $r){$l=SponsorshipLead::create(array_merge($this->data($r),['uuid'=>(string)Str::uuid()]));return to_route('admin.sponsorship-leads.show',$l);}public function show(SponsorshipLead $sponsorshipLead){return Inertia::render('Admin/Sponsorship/Leads/Show',['lead'=>$sponsorshipLead->load(['advertiser','owner','activities.user','proposals'])]);}public function edit(SponsorshipLead $sponsorshipLead){return Inertia::render('Admin/Sponsorship/Leads/Form',['lead'=>$sponsorshipLead,'advertisers'=>Advertiser::orderBy('name')->get(['id','name']),'users'=>User::orderBy('name')->get(['id','name'])]);}public function update(Request $r,SponsorshipLead $sponsorshipLead){$d=$this->data($r);if(($d['stage']??null)==='won')$d['won_at']=$sponsorshipLead->won_at?:now();if(($d['stage']??null)==='lost')$d['lost_at']=$sponsorshipLead->lost_at?:now();$sponsorshipLead->update($d);return to_route('admin.sponsorship-leads.show',$sponsorshipLead);}public function activity(Request $r,SponsorshipLead $sponsorshipLead){$d=$r->validate(['type'=>'required|in:note,email,call,meeting,task','subject'=>'required|string|max:255','details'=>'nullable|string','follow_up_at'=>'nullable|date']);$sponsorshipLead->activities()->create(array_merge($d,['user_id'=>$r->user()->id,'occurred_at'=>now()]));if(!empty($d['follow_up_at']))$sponsorshipLead->update(['next_follow_up_at'=>$d['follow_up_at']]);return back()->with('success','Sales activity recorded.');}private function data(Request $r):array{return $r->validate(['advertiser_id'=>'nullable|exists:advertisers,id','assigned_to'=>'nullable|exists:users,id','company_name'=>'required|string|max:255','contact_name'=>'nullable|string|max:255','contact_email'=>'nullable|email|max:255','contact_phone'=>'nullable|string|max:50','source'=>'nullable|string|max:100','stage'=>'required|in:'.implode(',',SponsorshipLead::STAGES),'estimated_value_cents'=>'required|integer|min:0','probability'=>'required|integer|min:0|max:100','target_close_date'=>'nullable|date','next_follow_up_at'=>'nullable|date','notes'=>'nullable|string','lost_reason'=>'nullable|string|max:255']);}}
